"use client";

import { useEffect, useRef } from "react";
import { preload } from "react-dom";
import { cn } from "@/lib/utils";
import { BESIDE_QUERY, frameFor } from "./framing";
import { mountGoldenGate, type GoldenGate } from "./live";
import "./golden-gate.css";

// Generated by `npm run golden-gate:build` from scripts/golden-gate.
const SCENE_URL = "/golden-gate/north-tower.svg";

export function GoldenGateScene({ className }: { className?: string }) {
  // Matches fetch()'s default same-origin CORS request so the browser reuses the preload.
  preload(SCENE_URL, { as: "fetch", crossOrigin: "anonymous" });
  const stageRef = useRef<HTMLDivElement>(null);
  const hostRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const stage = stageRef.current;
    const host = hostRef.current;
    if (!stage || !host) return;
    const controller = new AbortController();
    const beside = matchMedia(BESIDE_QUERY);
    let resizeObserver: ResizeObserver | undefined;
    let scene: GoldenGate | undefined;
    let reveal = 0;

    const frame = () => {
      const { width, height } = stage.getBoundingClientRect();
      if (!width || !height) return;
      scene?.setView(frameFor(width, height, beside.matches));
    };

    fetch(SCENE_URL, { signal: controller.signal })
      .then((response) => {
        if (!response.ok) throw new Error(`HTTP ${response.status}`);
        return response.text();
      })
      .then((markup) => {
        // A static file from this origin, written by the build script.
        host.innerHTML = markup;
        const svg = host.querySelector("svg");
        if (!svg) return;
        svg.setAttribute("preserveAspectRatio", "xMidYMid slice");
        scene = mountGoldenGate(stage, svg);
        frame();
        resizeObserver = new ResizeObserver(frame);
        resizeObserver.observe(stage);
        beside.addEventListener("change", frame);
        reveal = requestAnimationFrame(() => stage.setAttribute("data-ready", ""));
      })
      .catch((error: unknown) => {
        if (!controller.signal.aborted) console.error("The Golden Gate scene could not load.", error);
      });

    return () => {
      controller.abort();
      cancelAnimationFrame(reveal);
      resizeObserver?.disconnect();
      beside.removeEventListener("change", frame);
      scene?.destroy();
      host.replaceChildren();
      stage.removeAttribute("data-ready");
    };
  }, []);

  return (
    <div ref={stageRef} className={cn("gg-scene", className)}>
      <div ref={hostRef} className="gg-scene-host" />
    </div>
  );
}
